window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f2fba2676e2fac5e"]={"versions": [{"id": "FIG-f2fba2676e2fac5e", "releases": ["R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Adaptive-Metamodells im Manifest-Kontext (TPS_ManifestSpecification). Es definiert die Container- und Kompositionsstruktur für das Mapping von Service-Schnittstellen und deren Elementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>ServiceInterfaceMappingSet</code>: Spezialisierung von <code>ARElement</code>, fungiert als Paketierungs- und Wurzelelement für Service-Mappings.</li>\n<li><code>ServiceInterfaceMapping</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert das Mapping auf Schnittstellenebene. Ist über die Kompositionsrolle <code>+interfaceMapping</code> mit der Multiplizität <code>0..*</code> in <code>ServiceInterfaceMappingSet</code> aggregiert.</li>\n<li><code>ServiceInterfaceElementMapping</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert das Mapping auf Ebene einzelner Schnittstellenelemente. Ist über die Kompositionsrolle <code>+elementMapping</code> mit der Multiplizität <code>0..*</code> in <code>ServiceInterfaceMappingSet</code> aggregiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltensbeschreibungen oder Sequenzabläufe. Die Instanziierung erfolgt deklarativ über ARXML-Manifeste im Rahmen der Modellierung und Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>ServiceInterfaceMappingSet</code> dient als eigenständiges Top-Level-Modellelement (<code>ARElement</code>) zur Bündelung von Schnittstellen- und Element-Mappings. Die Kardinalitäten <code>0..*</code> erlauben leere Sets sowie beliebige Kombinationen von Mappings für Services und deren Einzelelemente. Beide Mapping-Klassen erben von <code>Identifiable</code> und besitzen somit standardisierte Metadaten wie Kurznamen (<code>shortName</code>).</p>"}, {"id": "FIG-a321aae06e1b721c", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Adaptive-Metamodells im Manifest-Kontext (TPS_ManifestSpecification). Es definiert die Container- und Kompositionsstruktur für das Mapping von Service-Schnittstellen und deren Elementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>ServiceInterfaceMappingSet</code>: Spezialisierung von <code>ARElement</code>, fungiert als Paketierungs- und Wurzelelement für Service-Mappings.</li>\n<li><code>ServiceInterfaceMapping</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert das Mapping auf Schnittstellenebene. Ist über die Kompositionsrolle <code>+interfaceMapping</code> mit der Multiplizität <code>0..*</code> in <code>ServiceInterfaceMappingSet</code> aggregiert.</li>\n<li><code>ServiceInterfaceElementMapping</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert das Mapping auf Ebene einzelner Schnittstellenelemente. Ist über die Kompositionsrolle <code>+elementMapping</code> mit der Multiplizität <code>0..*</code> in <code>ServiceInterfaceMappingSet</code> aggregiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltensbeschreibungen oder Sequenzabläufe. Die Instanziierung erfolgt deklarativ über ARXML-Manifeste im Rahmen der Modellierung und Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>ServiceInterfaceMappingSet</code> dient als eigenständiges Top-Level-Modellelement (<code>ARElement</code>) zur Bündelung von Schnittstellen- und Element-Mappings. Die Kardinalitäten <code>0..*</code> erlauben leere Sets sowie beliebige Kombinationen von Mappings für Services und deren Einzelelemente. Beide Mapping-Klassen erben von <code>Identifiable</code> und besitzen somit standardisierte Metadaten wie Kurznamen (<code>shortName</code>).</p>"}, {"id": "FIG-eb028dc77b619ce3", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Adaptive-Metamodells im Manifest-Kontext (TPS_ManifestSpecification). Es definiert die Container- und Kompositionsstruktur für das Mapping von Service-Schnittstellen und deren Elementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>ServiceInterfaceMappingSet</code>: Spezialisierung von <code>ARElement</code>, fungiert als Paketierungs- und Wurzelelement für Service-Mappings.</li>\n<li><code>ServiceInterfaceMapping</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert das Mapping auf Schnittstellenebene. Ist über die Kompositionsrolle <code>+interfaceMapping</code> mit der Multiplizität <code>0..*</code> in <code>ServiceInterfaceMappingSet</code> aggregiert.</li>\n<li><code>ServiceInterfaceElementMapping</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert das Mapping auf Ebene einzelner Schnittstellenelemente. Ist über die Kompositionsrolle <code>+elementMapping</code> mit der Multiplizität <code>0..*</code> in <code>ServiceInterfaceMappingSet</code> aggregiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltensbeschreibungen oder Sequenzabläufe. Die Instanziierung erfolgt deklarativ über ARXML-Manifeste im Rahmen der Modellierung und Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>ServiceInterfaceMappingSet</code> dient als eigenständiges Top-Level-Modellelement (<code>ARElement</code>) zur Bündelung von Schnittstellen- und Element-Mappings. Die Kardinalitäten <code>0..*</code> erlauben leere Sets sowie beliebige Kombinationen von Mappings für Services und deren Einzelelemente. Beide Mapping-Klassen erben von <code>Identifiable</code> und besitzen somit standardisierte Metadaten wie Kurznamen (<code>shortName</code>).</p>"}, {"id": "FIG-dbd1cf2f2f628c71", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Adaptive-Metamodells im Manifest-Kontext (TPS_ManifestSpecification). Es definiert die Container- und Kompositionsstruktur für das Mapping von Service-Schnittstellen und deren Elementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>ServiceInterfaceMappingSet</code>: Spezialisierung von <code>ARElement</code>, fungiert als Paketierungs- und Wurzelelement für Service-Mappings.</li>\n<li><code>ServiceInterfaceMapping</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert das Mapping auf Schnittstellenebene. Ist über die Kompositionsrolle <code>+interfaceMapping</code> mit der Multiplizität <code>0..*</code> in <code>ServiceInterfaceMappingSet</code> aggregiert.</li>\n<li><code>ServiceInterfaceElementMapping</code>: Spezialisierung von <code>Identifiable</code>, repräsentiert das Mapping auf Ebene einzelner Schnittstellenelemente. Ist über die Kompositionsrolle <code>+elementMapping</code> mit der Multiplizität <code>0..*</code> in <code>ServiceInterfaceMappingSet</code> aggregiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltensbeschreibungen oder Sequenzabläufe. Die Instanziierung erfolgt deklarativ über ARXML-Manifeste im Rahmen der Modellierung und Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>ServiceInterfaceMappingSet</code> dient als eigenständiges Top-Level-Modellelement (<code>ARElement</code>) zur Bündelung von Schnittstellen- und Element-Mappings. Die Kardinalitäten <code>0..*</code> erlauben leere Sets sowie beliebige Kombinationen von Mappings für Services und deren Einzelelemente. Beide Mapping-Klassen erben von <code>Identifiable</code> und besitzen somit standardisierte Metadaten wie Kurznamen (<code>shortName</code>).</p>"}], "trans": [{"from": "FIG-f2fba2676e2fac5e", "to": "FIG-a321aae06e1b721c", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a321aae06e1b721c", "to": "FIG-eb028dc77b619ce3", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Attributtrennlinien: In den Klassen <code>ServiceInterfaceMappingSet</code>, <code>ServiceInterfaceMapping</code> und <code>ServiceInterfaceElementMapping</code> wurden die horizontalen Trennlinien zum leeren Attribut-/Operationsbereich entfernt.</li>\n</ul>"}, {"from": "FIG-eb028dc77b619ce3", "to": "FIG-dbd1cf2f2f628c71", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Diagrammlayout: Die vertikalen Kompositionslinien zwischen <code>ServiceInterfaceMappingSet</code> und den Zielklassen <code>ServiceInterfaceMapping</code> bzw. <code>ServiceInterfaceElementMapping</code> wurden verkürzt (kompakteres Layout).</li>\n</ul>"}]};
